#!/usr/bin/env bash
# session-start-caveman.sh
# Auto-activates Caveman (https://github.com/juliusbrussee/caveman) for the
# session so every agent inherits compressed output by default.
#
# Caveman is installed once per machine (see scripts/install-caveman.sh) but
# its `/caveman` activation is a per-session command. This hook emits the
# activation directive on session start; on tools that don't read stdout
# from session hooks (Cursor, Antigravity), the rule files generated by
# `caveman --with-init` carry the same effect.

set -euo pipefail

MODE="${ADS_CAVEMAN_MODE:-full}"   # lite|full|ultra|wenyan

export CAVEMAN_STATUSLINE_SAVINGS="${CAVEMAN_STATUSLINE_SAVINGS:-0}"

if ! command -v caveman >/dev/null 2>&1; then
  echo "[caveman] not installed — run scripts/install-caveman.sh once" >&2
  exit 0
fi

echo "[caveman] activate mode=$MODE"
echo "/caveman $MODE"
